from __future__ import annotations

import json
import sys
from pathlib import Path


GENERATED_HEADER = """# Generated by experiments/pearson_robot/scripts/build_rhino_script.py.
# Do not edit by hand. Edit robot_recipe.json and regenerate.
"""


RUNTIME_CODE = r'''
import json
import math
import System

import Rhino
import rhinoscriptsyntax as rs
import scriptcontext as sc


ROBOT_RECIPE = __ROBOT_RECIPE_JSON__


def ensure_layer(layer_path):
    current_path = ""
    parent_id = System.Guid.Empty
    for name in layer_path.split("::"):
        current_path = name if not current_path else current_path + "::" + name
        layer_index = sc.doc.Layers.FindByFullPath(current_path, True)
        if layer_index >= 0:
            parent_id = sc.doc.Layers[layer_index].Id
            continue

        layer = Rhino.DocObjects.Layer()
        layer.Name = name
        if parent_id != System.Guid.Empty:
            layer.ParentLayerId = parent_id
        layer_index = sc.doc.Layers.Add(layer)
        parent_id = sc.doc.Layers[layer_index].Id
    return sc.doc.Layers.FindByFullPath(layer_path, True)


def ensure_material(name, diffuse):
    material_index = sc.doc.Materials.Find(name, True)
    if material_index >= 0:
        material = sc.doc.Materials[material_index]
        material.DiffuseColor = System.Drawing.Color.FromArgb(diffuse[0], diffuse[1], diffuse[2])
        sc.doc.Materials.Modify(material, material_index, True)
        return material_index

    material = Rhino.DocObjects.Material()
    material.Name = name
    material.DiffuseColor = System.Drawing.Color.FromArgb(diffuse[0], diffuse[1], diffuse[2])
    return sc.doc.Materials.Add(material)


def rotation_xform(rotation_degrees):
    rx, ry, rz = [math.radians(value) for value in rotation_degrees]
    xform = Rhino.Geometry.Transform.Identity
    xform = xform * Rhino.Geometry.Transform.Rotation(rx, Rhino.Geometry.Vector3d.XAxis, Rhino.Geometry.Point3d.Origin)
    xform = xform * Rhino.Geometry.Transform.Rotation(ry, Rhino.Geometry.Vector3d.YAxis, Rhino.Geometry.Point3d.Origin)
    xform = xform * Rhino.Geometry.Transform.Rotation(rz, Rhino.Geometry.Vector3d.ZAxis, Rhino.Geometry.Point3d.Origin)
    return xform


def translation_xform(vector):
    return Rhino.Geometry.Transform.Translation(vector[0], vector[1], vector[2])


def frame_world_transform(frame_id, frames_by_id, cache):
    if frame_id in cache:
        return cache[frame_id]

    frame = frames_by_id[frame_id]
    local = translation_xform(frame["origin"]) * rotation_xform(frame["rotation_degrees"])
    parent_id = frame.get("parent")
    if parent_id:
        world = frame_world_transform(parent_id, frames_by_id, cache) * local
    else:
        world = local
    cache[frame_id] = world
    return world


def part_transform(part, frame_transform):
    local = translation_xform(part["center"]) * rotation_xform(part["rotation_degrees"])
    return frame_transform * local


def create_oriented_box(size, transform):
    sx, sy, sz = size
    plane = Rhino.Geometry.Plane.WorldXY
    box = Rhino.Geometry.Box(
        plane,
        Rhino.Geometry.Interval(-sx / 2.0, sx / 2.0),
        Rhino.Geometry.Interval(-sy / 2.0, sy / 2.0),
        Rhino.Geometry.Interval(-sz / 2.0, sz / 2.0),
    )
    brep = box.ToBrep()
    brep.Transform(transform)
    return brep


def create_wedge(size, transform, slope):
    sx, sy, sz = size
    x0, x1 = -sx / 2.0, sx / 2.0
    y0, y1 = -sy / 2.0, sy / 2.0
    z0, z1 = -sz / 2.0, sz / 2.0
    dz0 = -slope * sz / 2.0
    dz1 = slope * sz / 2.0

    points = [
        Rhino.Geometry.Point3d(x0, y0, z0),
        Rhino.Geometry.Point3d(x1, y0, z0),
        Rhino.Geometry.Point3d(x1, y1, z0),
        Rhino.Geometry.Point3d(x0, y1, z0),
        Rhino.Geometry.Point3d(x0, y0, z1 + dz0),
        Rhino.Geometry.Point3d(x1, y0, z1 + dz0),
        Rhino.Geometry.Point3d(x1, y1, z1 + dz1),
        Rhino.Geometry.Point3d(x0, y1, z1 + dz1),
    ]
    mesh = Rhino.Geometry.Mesh()
    for point in points:
        mesh.Vertices.Add(point)
    mesh.Faces.AddFace(0, 1, 2, 3)
    mesh.Faces.AddFace(4, 7, 6, 5)
    mesh.Faces.AddFace(0, 4, 5, 1)
    mesh.Faces.AddFace(1, 5, 6, 2)
    mesh.Faces.AddFace(2, 6, 7, 3)
    mesh.Faces.AddFace(3, 7, 4, 0)
    mesh.Normals.ComputeNormals()
    mesh.Compact()
    mesh.Transform(transform)
    return mesh


def add_part_object(part, geometry, recipe, material_indices):
    layer_path = recipe["layers"][part["layer"]]
    layer_index = ensure_layer(layer_path)
    attributes = Rhino.DocObjects.ObjectAttributes()
    attributes.Name = part["id"]
    attributes.LayerIndex = layer_index
    attributes.MaterialSource = Rhino.DocObjects.ObjectMaterialSource.MaterialFromObject
    attributes.MaterialIndex = material_indices[part["material"]]
    attributes.SetUserString("rook.part_id", part["id"])
    attributes.SetUserString("rook.part_type", part["type"])
    attributes.SetUserString("rook.parent", part["parent"])
    attributes.SetUserString("rook.role", part["role"])
    attributes.SetUserString("rook.frame", part["frame"])
    attributes.SetUserString("rook.recipe_revision", recipe["revision"])
    attributes.SetUserString("rook.source_strategy", "semantic_parametric_reconstruction")
    attributes.SetUserString("rook.reference_folder", r"H:\AI EXPERIMENTS\Pearson\reference_images\ROBOT")
    if isinstance(geometry, Rhino.Geometry.Mesh):
        return sc.doc.Objects.AddMesh(geometry, attributes)
    return sc.doc.Objects.AddBrep(geometry, attributes)


def set_document_metadata(recipe):
    sc.doc.Strings.SetString("rook.project", recipe["project"])
    sc.doc.Strings.SetString("rook.units", "meters")
    sc.doc.Strings.SetString("rook.reference_folder", r"H:\AI EXPERIMENTS\Pearson\reference_images\ROBOT")
    sc.doc.Strings.SetString("rook.target_fidelity", "recognizable_study_model")
    sc.doc.Strings.SetString("rook.modeling_strategy", "semantic_parametric_reconstruction")
    sc.doc.Strings.SetString("rook.active_recipe", r"experiments\pearson_robot\robot_recipe.json")
    sc.doc.Strings.SetString("rook.recipe_revision", recipe["revision"])


def make_named_views(recipe):
    for view in recipe["named_views"]:
        rs.ViewCameraTarget(None, tuple(view["camera_location"]), tuple(view["target"]))
        rs.ViewProjection(None, 2)
        try:
            rs.ViewCameraLens(None, view["lens_length"])
        except Exception:
            pass

        existing = sc.doc.NamedViews.FindByName(view["name"])
        if existing >= 0:
            sc.doc.NamedViews.Delete(existing)
        active_view = sc.doc.Views.ActiveView
        if active_view is not None:
            sc.doc.NamedViews.Add(view["name"], active_view.ActiveViewportID)


def clear_previous_robot():
    ids = rs.AllObjects()
    if not ids:
        return
    delete_ids = []
    for object_id in ids:
        if rs.GetUserText(object_id, "rook.source_strategy") == "semantic_parametric_reconstruction":
            delete_ids.append(object_id)
    if delete_ids:
        rs.DeleteObjects(delete_ids)


def main():
    recipe = ROBOT_RECIPE
    set_document_metadata(recipe)
    for layer_path in recipe["layers"].values():
        ensure_layer(layer_path)

    material_indices = {}
    for name, material in recipe["materials"].items():
        material_indices[name] = ensure_material(name, material["diffuse"])

    clear_previous_robot()
    frames_by_id = {frame["id"]: frame for frame in recipe["frames"]}
    frame_cache = {}
    created = []
    for part in recipe["parts"]:
        frame_transform = frame_world_transform(part["frame"], frames_by_id, frame_cache)
        transform = part_transform(part, frame_transform)
        if part["type"] == "wedge":
            geometry = create_wedge(part["size"], transform, part.get("slope", 0.0))
        else:
            geometry = create_oriented_box(part["size"], transform)
        created.append(str(add_part_object(part, geometry, recipe, material_indices)))

    make_named_views(recipe)
    sc.doc.Views.Redraw()
    print(json.dumps({
        "success": True,
        "created_count": len(created),
        "created_ids": created,
        "revision": recipe["revision"],
    }, sort_keys=True))


main()
'''


def build_script(recipe_path: Path) -> str:
    recipe = json.loads(recipe_path.read_text(encoding="utf-8"))
    payload = json.dumps(recipe, indent=2, sort_keys=True)
    code = RUNTIME_CODE.replace("__ROBOT_RECIPE_JSON__", "json.loads(" + repr(payload) + ")")
    return GENERATED_HEADER + "\n" + code


def main(argv: list[str]) -> int:
    if len(argv) != 3:
        print("usage: build_rhino_script.py <recipe.json> <output.py>", file=sys.stderr)
        return 2

    recipe_path = Path(argv[1])
    output_path = Path(argv[2])
    output_path.parent.mkdir(parents=True, exist_ok=True)
    output_path.write_text(build_script(recipe_path), encoding="utf-8")
    print(f"wrote {output_path}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
